#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    int findLHS(vector<int>& nums) {
        unordered_map<int, int> freq;
        int result = 0;
        for (int num : nums) freq[num]++;
        for (auto& [num, count] : freq) {
            if (freq.count(num + 1)) {
                result = max(result, count + freq[num + 1]);
            }
        }
        return result;
    }
};
